
--[=[
    @interface ITransition
    过渡动画接口，用于定义面板切换时的过渡效果
]=]
export type TransitionResult = {
    direction: "Bottom" | "Front" | "Back" | "Top",
    tweenInfo: TweenInfo?,
    target: GuiObject?
}

export type ITransition = {
    --[=[
        应用进入过渡动画
        @param container View 容器视图
        @param panel View 面板视图
        @return TransitionResult 过渡动画配置
    ]=]
    ApplyTransitionIn: (self: ITransition, container: INZView, panel: INZView) -> TransitionResult,

    --[=[
        应用退出过渡动画
        @param container View 容器视图
        @param panel View 面板视图
        @return TransitionResult 过渡动画配置
    ]=]
    ApplyTransitionOut: (self: ITransition, container: INZView, panel: INZView) -> TransitionResult
}

return {}